import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getFollow } from "../handlers/getFollow";
import type { ApiError } from "../runtime/client";
import type { SpaceActionFollowEntityType } from "../types/SpaceActionFollowEntityType";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof getFollow>>;

export function useGetFollow(
  spacePk: SpacePartition,
  followId: SpaceActionFollowEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getFollow", spacePk, followId],
    queryFn: () => getFollow(spacePk, followId),
    ...options,
  });
}
